### Pull Request #42: Refactor authentication flow

**Description:** This PR introduces a new token handling mechanism and cleans up the login utility functions.

**Changes:**
- **src/auth/tokenManager.js** (new file) – implements `generateToken` and `validateToken`.
- **src/utils/helpers.js** – updated with new helper functions and removed deprecated ones.

```diff
--- a/src/utils/helpers.js
+++ b/src/utils/helpers.js
@@
-function hashPassword(password) {
-  // Old SHA1 based hashing (insecure)
-  return crypto.createHash('sha1').update(password).digest('hex');
-}
+function hashPassword(password) {
+  // Updated to use bcrypt
+  const salt = bcrypt.genSaltSync(12);
+  return bcrypt.hashSync(password, salt);
+}

-function generateRandomString(length) {
-  return Math.random().toString(36).substring(2, 2 + length);
-}
+function generateRandomString(length) {
+  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
+  let result = '';
+  for (let i = 0; i < length; i++) {
+    result += chars.charAt(Math.floor(Math.random() * chars.length));
+  }
+  return result;
+}
+
+function parseJwt(token) {
+  const base64Url = token.split('.')[1];
+  const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
+  return JSON.parse(window.atob(base64));
+}
```

