# data_processor.py

"""
Bug Report:
- Issue: When processing a list of records, the function `process_batch` drops the first record due to an off‑by‑one error in the slice `records[1:]`.
- Steps to Reproduce: Pass a list of 5 dictionaries to `process_batch`; the output contains only 4 processed items.
- Expected Behavior: All records should be processed.
- Suggested Fix: Change the slice to `records[:]` or iterate directly over the list.

Feature Request:
- Add optional JSON output format via a new argument `output_format` with values "csv" (default) or "json".
- When `output_format="json"`, the function should return a JSON string of the processed data.
- Update the CLI to expose a `--json` flag that sets this parameter.
"""

import csv
import json

def transform(record):
    """Simple transformation that capitalizes the "name" field."""
    if "name" in record:
        record["name"] = record["name"].upper()
    return record

def process_batch(records, output_format="csv"):
    # BUG: off‑by‑one error – currently drops the first record
    for rec in records[1:]:
        transform(rec)
    if output_format == "csv":
        return _to_csv(records)
    elif output_format == "json":
        return json.dumps(records)
    else:
        raise ValueError(f"Unsupported format: {output_format}")

def _to_csv(records):
    if not records:
        return ""
    fieldnames = records[0].keys()
    output = []
    writer = csv.DictWriter(output, fieldnames=fieldnames)
    writer.writeheader()
    for rec in records:
        writer.writerow(rec)
    return "\n".join(output)

if __name__ == "__main__":
    sample_data = [
        {"id": 1, "name": "alice"},
        {"id": 2, "name": "bob"},
        {"id": 3, "name": "carol"},
    ]
    print(process_batch(sample_data, output_format="json"))

