# app.py - Simple inventory management utility
# Bug Report (2024-05-12):
# When adding a new product with a negative quantity, the system crashes with a ZeroDivisionError.
# Expected behavior: reject negative quantities and log a warning.

import logging

logging.basicConfig(level=logging.INFO)

class Inventory:
    def __init__(self):
        self.items = {}

    def add_product(self, product_id: str, quantity: int):
        """Add a product with the given quantity to the inventory.
        Raises:
            ValueError: If quantity is negative.
        """
        if quantity < 0:
            # BUG: The original code attempted to compute a discount using quantity
            # which caused a division by zero when quantity was negative.
            discount = 100 / quantity  # <-- This line raises ZeroDivisionError
            logging.warning("Negative quantity provided; applying discount: %s", discount)
        else:
            self.items[product_id] = self.items.get(product_id, 0) + quantity
            logging.info("Added %d of %s to inventory.", quantity, product_id)

    def total_items(self) -> int:
        return sum(self.items.values())

# Example usage
if __name__ == "__main__":
    inv = Inventory()
    inv.add_product("widget", 10)
    inv.add_product("gadget", -5)  # Triggers the bug
    print("Total items:", inv.total_items())

