# src/data_fetcher.py

"""
Bug Report #3421:
The fetch_data function sometimes raises a timeout error without retrying.
Feature Request:
Implement exponential backoff and configurable max retries.
"""

import requests
import time

def fetch_data(url):
    """Fetch data from URL with a single request."""
    response = requests.get(url, timeout=5)
    response.raise_for_status()
    return response.json()

def fetch_data_v2(url, max_retries=3, backoff_factor=0.5):
    """Fetch data with retry logic and exponential backoff."""
    for attempt in range(max_retries):
        try:
            response = requests.get(url, timeout=5)
            response.raise_for_status()
            return response.json()
        except (requests.exceptions.Timeout, requests.exceptions.HTTPError) as e:
            if attempt == max_retries - 1:
                raise
            sleep_time = backoff_factor * (2 ** attempt)
            time.sleep(sleep_time)

