**Description**
This PR addresses a race condition that occurs when multiple threads process data simultaneously, leading to occasional `IndexOutOfRangeException` crashes. The fix introduces a lock around the shared buffer and adds unit tests to cover the concurrency scenario.

**Changes**
```diff
--- a/src/DataProcessor.cs
+++ b/src/DataProcessor.cs
@@
-    private List<int> _buffer = new List<int>();
+    private readonly object _bufferLock = new object();
+    private List<int> _buffer = new List<int>();
@@
-    public void AddData(int value) {
-        _buffer.Add(value);
-    }
+    public void AddData(int value) {
+        lock (_bufferLock) {
+            _buffer.Add(value);
+        }
+    }
@@
-    public int GetData(int index) {
-        return _buffer[index];
-    }
+    public int GetData(int index) {
+        lock (_bufferLock) {
+            return _buffer[index];
+        }
+    }
```

