# bug_report.py
# Feature: Implement two sorting algorithms and report performance.
# Bug: sort_b fails on empty list.

def sort_a(lst):
    """Bubble sort implementation."""
    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst


def sort_b(lst):
    """Insertion sort implementation."""
    for i in range(1, len(lst)):
        key = lst[i]
        j = i-1
        while j >=0 and lst[j] > key:
            lst[j+1] = lst[j]
            j -= 1
        lst[j+1] = key
    # Missing return statement causes bug on empty list
    if not lst:
        raise ValueError("Cannot sort an empty list")

